CREATE TABLE IF NOT EXISTS waf_settings(id TINYINT UNSIGNED PRIMARY KEY DEFAULT 1,enabled BOOLEAN NOT NULL DEFAULT TRUE,mode ENUM('detection','blocking') NOT NULL DEFAULT 'detection',paranoia_level TINYINT UNSIGNED NOT NULL DEFAULT 1,inbound_threshold SMALLINT UNSIGNED NOT NULL DEFAULT 5,outbound_threshold SMALLINT UNSIGNED NOT NULL DEFAULT 4,updated_by BIGINT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
INSERT IGNORE INTO waf_settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS waf_custom_rules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rule_id INT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,target ENUM('uri','args','headers','user_agent') NOT NULL,operator ENUM('contains','regex','equals') NOT NULL DEFAULT 'contains',pattern VARCHAR(500) NOT NULL,action ENUM('log','block') NOT NULL DEFAULT 'log',active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,UNIQUE(rule_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS waf_exclusions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,path_prefix VARCHAR(500) NULL,ip VARCHAR(45) NULL,rule_id INT UNSIGNED NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS waf_deployments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,server_id BIGINT UNSIGNED NULL,status ENUM('queued','running','completed','failed') NOT NULL DEFAULT 'queued',mode ENUM('detection','blocking') NOT NULL,job_id CHAR(32) NULL,requested_by BIGINT UNSIGNED NOT NULL,output TEXT NULL,error_message TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,started_at TIMESTAMP NULL,completed_at TIMESTAMP NULL,FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL,FOREIGN KEY(requested_by) REFERENCES users(id),INDEX(status,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS waf_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source ENUM('modsecurity','barracuda','imported') NOT NULL DEFAULT 'modsecurity',server_id BIGINT UNSIGNED NULL,ip VARCHAR(45) NULL,rule_id VARCHAR(40) NULL,severity VARCHAR(30) NULL,method VARCHAR(12) NULL,path VARCHAR(1000) NULL,message TEXT NULL,action VARCHAR(30) NULL,occurred_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE SET NULL,INDEX(source,occurred_at),INDEX(ip,occurred_at),INDEX(rule_id,occurred_at)) ENGINE=InnoDB;
